package dev.kuan.kuanperion.automation.pest;
import dev.kuan.kuanperion.automation.*;import java.util.*;
public final class PestTaskBarnExchangeTest {
 static final long S=1_000_000_000L;static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static class P extends PestTaskExchangeTest.P {
  final PlayerPositionReceipts positions=new PlayerPositionReceipts();final List<PestPlot> sent=new ArrayList<>();final PestTargets.Point desk=new PestTargets.Point(1,70,1);final PestBarnTarget npc=new PestBarnTarget(88,UUID.randomUUID(),new PestTargets.Point(2,71.6,1));boolean known=true,bindReject,aiming,throwRelease;int binds;AutomationSession.Handle bound;
  public PestBarnTarget.Facts barnTargets(long n){return new PestBarnTarget.Facts(1,n,known,known?List.of(npc):List.of());}
  public PestTask.BarnReady bindBarnExchange(AutomationSession.Handle h,PestBarnTarget t,long n){check(session.isCurrent(h)&&session.holdsFarming()&&t.equals(npc),"bind exact original-root target, never acquire/rearm");binds++;bound=h;return bindReject?PestTask.BarnReady.REJECTED:aiming?PestTask.BarnReady.AIMING:PestTask.BarnReady.READY;}
  @Override public void release(AutomationSession.Handle h){if(throwRelease&&bound!=null)throw new IllegalStateException("Barn exchange startup release fault");super.release(h);}
  public PestTargets.Point position(){return base.pos;}
  public boolean travel(AutomationSession.Handle h,PestPlot p,long n){check(session.isCurrent(h)&&session.holdsFarming(),"travel preserves original root");sent.add(p);return true;}
  @Override public boolean openExchange(AutomationSession.Handle h,long n){check(h.equals(bound),"Barn interaction must follow exact target binder, no Abiphone fallback");return super.openExchange(h,n);}
 }
 static PestTask task(P p){return new PestTask(p.session,p,p.positions,p.coordinator,p.items,p.cursors);}
 static PestPolicy policy(P p){return PestPolicy.defaults().withExchangeAfterCleanup(true).withBarn(new PestBarnPolicy(true,p.desk));}
 static void cleanup(P p,PestTask t,PestPolicy policy){check(t.request(policy,true,p.now),"capture preflight");t.tick(p.now);p.now+=S;t.tick(p.now);p.base.alive=0;p.base.targets=List.of();p.now+=S;t.tick(p.now);}
 static void tick(P p,PestTask t){p.now+=100_000_000L;t.tick(p.now);}
 static void receipt(P p,PestTask t,PestTargets.Point destination){p.base.pos=destination;p.now+=S;p.positions.observe(1,p.sent.size(),new PlayerPositionReceipts.Position(destination.x(),destination.y(),destination.z()),true,p.now);t.tick(p.now);}
 public static void main(String[]args){
  var p=new P();var t=task(p);cleanup(p,t,policy(p));for(int i=0;i<30&&p.opens==0&&t.active();i++)tick(p,t);check(p.opens==1&&p.binds==1&&p.sent.isEmpty()&&p.base.restores==0,"local Barn -> explicit desk -> one target bind -> existing exchange, no teleport/call/return before proof "+t.state());p.show(false,true);for(int i=0;i<8&&p.clicks==0;i++)tick(p,t);check(p.clicks==1,"same private role/cursor/native bag proof");p.ack(true,true);for(int i=0;i<20&&t.active();i++)tick(p,t);check(t.state()==PestTask.State.COMPLETE&&t.confirmedExchanges()==1&&p.closes==1&&p.base.restores==1&&!p.session.active(),"local complete exchange then original restore under one root");
  p=new P();p.base.pos=new PestTargets.Point(0.5,70,-96);p.base.targets=List.of(new PestTargets.Target(20,PestTaskTest.TARGET.uuid(),PestTargets.Kind.BAT,new PestTargets.Point(5,71,-96),21));t=task(p);check(!t.request(policy(p),true,p.now)&&p.opens==0&&p.sent.isEmpty(),"Barn consent alone never authorizes cross-plot travel");
  p=new P();var home=new PestTargets.Point(.5,70,-96);p.base.pos=home;p.base.targets=List.of(new PestTargets.Target(20,PestTaskTest.TARGET.uuid(),PestTargets.Kind.BAT,new PestTargets.Point(5,71,-96),21));t=task(p);cleanup(p,t,policy(p).withTravelPlots(1));for(int i=0;i<12&&p.sent.isEmpty()&&t.active();i++)tick(p,t);check(p.sent.size()==1&&p.sent.getFirst().id()==0&&p.binds==0,"one typed Barn destination, no desk flight before applied arrival");for(int i=0;i<4;i++)tick(p,t);check(p.binds==0,"client prediction is not arrival");receipt(p,t,new PestTargets.Point(.5,70,.5));for(int i=0;i<20&&p.opens==0&&t.active();i++)tick(p,t);check(p.opens==1,"server Barn quorum precedes bounded desk/target route");p.show(true,true);for(int i=0;i<20&&p.sent.size()<2&&t.active();i++)tick(p,t);check(p.sent.size()==2&&p.sent.getLast().id()==1&&p.base.restores==0,"original source plot, not Barn spawn, remains exact return destination");receipt(p,t,home);for(int i=0;i<25&&t.active();i++)tick(p,t);check(t.state()==PestTask.State.COMPLETE&&p.base.restores==1&&p.base.pos.equals(home),"return absolute receipt then exact original pose before release "+t.state());
  for(String mode:List.of("missing","bind","manual","aim-timeout")){p=new P();if(mode.equals("missing"))p.known=false;if(mode.equals("bind"))p.bindReject=true;if(mode.equals("aim-timeout"))p.aiming=true;t=task(p);cleanup(p,t,policy(p));if(mode.equals("manual"))p.manual=true;for(int i=0;i<250&&t.active();i++)tick(p,t);check(!t.active()&&p.opens==0&&p.closes==0&&p.base.restores==0,"unknown/rejected/manual/bounded aim cannot call, interact, repair or pretend return "+mode+" "+t.state());}
  p=new P();p.throwRelease=true;t=task(p);cleanup(p,t,policy(p));for(int i=0;i<20&&p.binds==0&&t.active();i++)tick(p,t);check(!t.active()&&!p.session.active()&&p.opens==0,"fallible release at Barn-to-exchange transition must terminate in the same tick, not leave an inactive child under an active parent");
  System.out.println("PestTaskBarnExchangeTest: PASS real parent/exchange/receipts/travel models with controlled NPC edge; not live acceptance");
 }
}
